import{_ as n,a0 as o,w as r,s as p,ao as u,I as s,x as a,a1 as e,A as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"如何在 CentOS 8 / RHEL 8 上安裝 VirtualBox 6.0 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 CentOS 8 / RHEL 8 上安裝 VirtualBox 6.0 | LCTT (201911) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 CentOS 8 / RHEL 8 上安裝 VirtualBox 6.0 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 CentOS 8 / RHEL 8 上安裝 VirtualBox 6.0 | LCTT (201911) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201911/20191117 How to Install VirtualBox 6.0 on CentOS 8 - RHEL 8","title":"如何在 CentOS 8 / RHEL 8 上安裝 VirtualBox 6.0","tag":"201911","desc":""},"relativePath":"201911/20191117 How to Install VirtualBox 6.0 on CentOS 8 - RHEL 8.md","filePath":"[post].md"}'),d={name:"201911/20191117 How to Install VirtualBox 6.0 on CentOS 8 - RHEL 8.md"};function h(c,t,x,g,b,k){const i=o("Link");return r(),p("div",null,[t[15]||(t[15]=u(`<h1 id="如何在-centos-8-rhel-8-上安裝-virtualbox-6-0" tabindex="-1">如何在 CentOS 8 / RHEL 8 上安裝 VirtualBox 6.0 <a class="header-anchor" href="#如何在-centos-8-rhel-8-上安裝-virtualbox-6-0" aria-label="Permalink to “如何在 CentOS 8 / RHEL 8 上安裝 VirtualBox 6.0”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/201911/30/095031gbnm59ux0dw979wb.jpg" alt=""></p><p>VirtualBox 是一款自由開源的虛擬化工具，它允許技術人員同時運行多個不同風格的虛擬機（VM）。它通常用於運行桌面（Linux 和 Windows），當人們嘗試探索新的 Linux 發行版的功能或希望在 VM 中安裝 OpenStack、Ansible 和 Puppet 等軟件時，它會非常方便，在這種情況下，我們可以使用 VirtualBox 啓動 VM。</p><p>VirtualBox 被分類為 2 類虛擬機管理程序，這意味着它需要一個現有的操作系統，在上面安裝 VirtualBox 軟件。VirtualBox 提供功能來創建本機網絡或 NAT 網絡。在本文中，我們將演示如何在 CentOS 8 和 RHEL 8 系統上安裝最新版本的 VirtualBox 6.0，並演示如何安裝 VirtualBox 擴展。</p><h3 id="在-centos-8-rhel-8-上安裝-virtualbox-6-0-的安裝步驟" tabindex="-1">在 CentOS 8 / RHEL 8 上安裝 VirtualBox 6.0 的安裝步驟 <a class="header-anchor" href="#在-centos-8-rhel-8-上安裝-virtualbox-6-0-的安裝步驟" aria-label="Permalink to “在 CentOS 8 / RHEL 8 上安裝 VirtualBox 6.0 的安裝步驟”">​</a></h3><h4 id="步驟-1-啓用-virtualbox-和-epel-倉庫" tabindex="-1">步驟 1： 啓用 VirtualBox 和 EPEL 倉庫 <a class="header-anchor" href="#步驟-1-啓用-virtualbox-和-epel-倉庫" aria-label="Permalink to “步驟 1： 啓用 VirtualBox 和 EPEL 倉庫”">​</a></h4><p>登錄到你的 CentOS 8 或 RHEL 8 系統並打開終端，執行以下命令並啓用 VirtualBox 和 EPEL 包倉庫：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# dnf config-manager --add-repo=https://download.virtualbox.org/virtualbox/rpm/el/virtualbox.repo</span></span></code></pre></div><p>使用以下 <code>rpm</code> 命令導入 Oracle VirtualBox 公鑰：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# rpm --import https://www.virtualbox.org/download/oracle_vbox.asc</span></span></code></pre></div><p>使用以下 <code>dnf</code> 命令啓用 EPEL 倉庫：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# dnf install https://dl.fedoraproject.org/pub/epel/epel-release-latest-8.noarch.rpm -y</span></span></code></pre></div><h4 id="步驟-2-安裝-virtualbox-構建工具和依賴項" tabindex="-1">步驟 2： 安裝 VirtualBox 構建工具和依賴項 <a class="header-anchor" href="#步驟-2-安裝-virtualbox-構建工具和依賴項" aria-label="Permalink to “步驟 2： 安裝 VirtualBox 構建工具和依賴項”">​</a></h4><p>運行以下命令來安裝所有 VirtualBox 構建工具和依賴項：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# dnf install binutils kernel-devel kernel-headers libgomp make patch gcc glibc-headers glibc-devel dkms -y</span></span></code></pre></div><p>成功安裝上面的依賴項和構建工具後，使用 <code>dnf</code> 命令繼續安裝 VirtualBox。</p><h4 id="步驟-3-在-centos-8-rhel-8-上安裝-virtualbox-6-0" tabindex="-1">步驟 3： 在 CentOS 8 / RHEL 8 上安裝 VirtualBox 6.0 <a class="header-anchor" href="#步驟-3-在-centos-8-rhel-8-上安裝-virtualbox-6-0" aria-label="Permalink to “步驟 3： 在 CentOS 8 / RHEL 8 上安裝 VirtualBox 6.0”">​</a></h4><p>如果希望在安裝之前列出 VirtualBox 的可用版本，請執行以下 dnf 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# dnf search virtualbox</span></span>
<span class="line"><span>Last metadata expiration check: 0:14:36 ago on Sun 17 Nov 2019 04:13:16 AM GMT.</span></span>
<span class="line"><span>=============== Summary &amp; Name Matched: virtualbox =====================</span></span>
<span class="line"><span>VirtualBox-5.2.x86_64 : Oracle VM VirtualBox</span></span>
<span class="line"><span>VirtualBox-6.0.x86_64 : Oracle VM VirtualBox</span></span>
<span class="line"><span>[root@linuxtechi ~]#</span></span></code></pre></div><p>讓我們使用以下 <code>dnf</code> 命令安裝最新版本的 VirtualBox 6.0：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# dnf install VirtualBox-6.0 -y</span></span></code></pre></div><p>如果有本地用户希望將 usb 設備連接到 VirtualBox VM，那麼他/她應該是 <code>vboxusers</code> 組的一員，請使用下面的 <code>usermod</code> 命令將本地用户添加到 <code>vboxusers</code> 組。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# usermod -aG vboxusers pkumar</span></span></code></pre></div><h4 id="步驟-4-訪問-centos-8-rhel-8-上的-virtualbox" tabindex="-1">步驟 4： 訪問 CentOS 8 / RHEL 8 上的 VirtualBox <a class="header-anchor" href="#步驟-4-訪問-centos-8-rhel-8-上的-virtualbox" aria-label="Permalink to “步驟 4： 訪問 CentOS 8 / RHEL 8 上的 VirtualBox”">​</a></h4><p>有兩種方法可以訪問 VirtualBox，在命令列輸入 <code>virtualbox</code> 然後回車：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# virtualbox</span></span></code></pre></div><p>在桌面環境中，在搜索框中搜索 “VirtualBox”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/11/Access-VirtualBox-CentOS8.jpg" alt="Access-VirtualBox-CentOS8"></p><p>單擊 VirtualBox 圖標：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/11/VirtualBox-CentOS8.jpg" alt="VirtualBox-CentOS8"></p><p>這確認 VirtualBox 6.0 已成功安裝，讓我們安裝它的擴展包。</p><h4 id="步驟-5-安裝-virtualbox-6-0-擴展包" tabindex="-1">步驟 5： 安裝 VirtualBox 6.0 擴展包 <a class="header-anchor" href="#步驟-5-安裝-virtualbox-6-0-擴展包" aria-label="Permalink to “步驟 5： 安裝 VirtualBox 6.0 擴展包”">​</a></h4><p>顧名思義，VirtualBox 擴展包用於擴展 VirtualBox 的功能。它添加了以下功能：</p><ul><li>USB 2.0 和 USB 3.0 支持</li><li>虛擬 RDP（VRDP）</li><li>磁盤鏡像加密</li><li>Intel PXE 啓動</li><li>主機網絡攝像頭</li></ul><p>使用下面的 <code>wget</code> 命令下載 Virtualbox 擴展包到下載文件夾中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]$ cd Downloads/</span></span>
<span class="line"><span>[root@linuxtechi Downloads]$ wget https://download.virtualbox.org/virtualbox/6.0.14/Oracle_VM_VirtualBox_Extension_Pack-6.0.14.vbox-extpack</span></span></code></pre></div><p>下載後，打開 VirtualBox 並依次點擊 “File -&gt; Preferences -&gt; Extension”，然後點擊 “+” 號圖標添加下載的擴展包：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/11/Install-VirtualBox-Extension-Pack-CentOS8.jpg" alt="Install-VirtualBox-Extension-Pack-CentOS8"></p><p>單擊 “Install” 開始安裝擴展包：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/11/Accept-VirtualBox-Extension-Pack-License-CentOS8.jpg" alt="Accept-VirtualBox-Extension-Pack-License-CentOS8"></p><p>單擊 “I Agree” 接受 VirtualBox 擴展包許可證。</p><p>成功安裝 VirtualBox 擴展包後，我們將看到下面的頁面，單擊 “OK” 並開始使用 VirtualBox。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/11/VirtualBox-Extension-Pack-Install-Message-CentOS8.jpg" alt="VirtualBox-Extension-Pack-Install-Message-CentOS8"></p><p>本文就是這些了，我希望這些步驟可以幫助你在 CentOS 8 和 RHEL 8 系統上安裝 VirtualBox 6.0。請分享你的寶貴的反饋和意見。</p><hr>`,45)),s("p",null,[t[1]||(t[1]=a("via: ",-1)),e(i,{href:"https://www.linuxtechi.com/install-virtualbox-6-centos-8-rhel-8/"},{default:l(()=>[...t[0]||(t[0]=[a("https://www.linuxtechi.com/install-virtualbox-6-centos-8-rhel-8/",-1)])]),_:1})]),s("p",null,[t[6]||(t[6]=a("作者：",-1)),e(i,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:l(()=>[...t[2]||(t[2]=[a("Pradeep Kumar",-1)])]),_:1}),t[7]||(t[7]=a(" 選題：",-1)),e(i,{href:"https://github.com/lujun9972"},{default:l(()=>[...t[3]||(t[3]=[a("lujun9972",-1)])]),_:1}),t[8]||(t[8]=a(" 譯者：",-1)),e(i,{href:"https://github.com/geekpi"},{default:l(()=>[...t[4]||(t[4]=[a("geekpi",-1)])]),_:1}),t[9]||(t[9]=a(" 校對：",-1)),e(i,{href:"https://github.com/wxy"},{default:l(()=>[...t[5]||(t[5]=[a("wxy",-1)])]),_:1})]),s("p",null,[t[12]||(t[12]=a("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[10]||(t[10]=[a("LCTT",-1)])]),_:1}),t[13]||(t[13]=a(" 原創編譯，",-1)),e(i,{href:"https://linux.cn/"},{default:l(()=>[...t[11]||(t[11]=[a("Linux中國",-1)])]),_:1}),t[14]||(t[14]=a(" 榮譽推出",-1))])])}const B=n(d,[["render",h]]);export{f as __pageData,B as default};
